#include "stock_alias_search.h"
#include <cassert>
#include <iostream>
void first(const char*q,const char*code){auto r=localStockMatches(q);assert(!r.empty()&&std::string(r[0]->code)==code);assert(r.size()<=8);}
int main(){for(auto q:{"kekokele","kkkl",u8"可口可乐","KO","ko","usKO","Coca-Cola"})first(q,"usKO");for(auto q:{"COKE","coke",u8"可口可乐瓶装",u8"可口可乐装瓶商"})first(q,"usCOKE");auto r=localStockMatches(u8"可口可乐");assert(r.size()>=2&&std::string(r[0]->code)=="usKO"&&std::string(r[1]->code)=="usCOKE");first("gzmt","sh600519");first("guizhoumaotai","sh600519");first("tesila","usTSLA");first("tsl","usTSLA");first("tx","hk00700");first("700","hk00700");first("00700","hk00700");first("BRK.B","usBRK.B");assert(localStockMatches("zhong",true).empty());assert(!localStockMatches("tengxun",true).empty());assert(localStockMatches("zzzzzz").empty());assert(localStockMatches("").empty());assert(localStockMatches(std::string(97,'a')).empty());auto a=localStockMatches("alibaba");assert(a.size()>=2);for(const auto&v:STOCK_ALIASES)first(v.code,v.code);std::cout<<"PASS full pinyin, initials, Chinese/English names, exact-code priority, KO/COKE distinction, shared market names, HK padding and bounded results\n";}
